// Format both candidate schemas into one readable report.
// Highlights the columns needed to build an everyone-level roster.
const WANT = {
  identity: ['employee_id', 'employee_name', 'employee_login_username', 'emid', 'employee', 'name', 'username'],
  email: ['email', 'emailaddress', 'employee_email', 'employee_email_address'],
  manager: ['manager', 'mgr', 'supervisor', 'leader'],
  date: ['date', 'snapshot', 'event_date', 'employee_date', 'reporting_date', 'datevalue'],
  workgroup: ['workgroup', 'wgid', 'wg_id', 'team', 'org'],
  active: ['active', 'still', 'is_current', 'currentflag', 'terminat'],
  level: ['level', 'rank', 'hierarchy', 'title', 'job'],
};

const collect = (nodeName) => {
  try {
    return $(nodeName).all().map((i) => i.json || {}).filter((r) => r.column_name);
  } catch (e) {
    return [];
  }
};

const sets = [
  ['gat-prod.ops_reporting_layer.vw_customer_service_master_reporting', collect('BigQuery - Schema A - master reporting')],
  ['cs-prod.cs_datawarehouse.vw_dim_employee_detail', collect('BigQuery - Schema B - dim employee detail')],
];

const L = [];
L.push('CANDIDATE SOURCE SCHEMAS for an everyone-level roster');
L.push('');

for (const [label, rows] of sets) {
  L.push('='.repeat(70));
  L.push(label);
  L.push('='.repeat(70));
  if (rows.length === 0) {
    L.push('  NO ACCESS or view does not exist - zero columns returned.');
    L.push('');
    continue;
  }
  L.push(`  ${rows.length} columns.`);
  L.push('');
  for (const [group, needles] of Object.entries(WANT)) {
    const hits = rows
      .filter((r) => needles.some((n) => String(r.column_name).toLowerCase().includes(n)))
      .map((r) => `${r.column_name} (${r.data_type})`);
    L.push(`  ${group.toUpperCase()}:`);
    if (hits.length === 0) L.push('    none found');
    else for (const h of hits) L.push(`    ${h}`);
  }
  L.push('');
  L.push('  ALL COLUMNS:');
  for (const r of rows) L.push(`    ${r.ordinal_position}. ${r.column_name} (${r.data_type})`);
  L.push('');
}

L.push('='.repeat(70));
L.push('Paste this whole report back to finish the everyone-level roster.');

const report = L.join('\n');
return [{ json: {
  report,
  master_reporting_column_count: sets[0][1].length,
  dim_employee_detail_column_count: sets[1][1].length,
} }];
